<script setup lang="ts">import {ref,onMounted} from 'vue';import {lots} from '../stores/lots';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {strata,strataLabels} from '../constants/enums';import {pct} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),stratum=ref('low'),size=ref(150),rate=ref(.03),prefix=ref(''),description=ref('');const {error,busy,act}=useTask();onMounted(lots.load);function submit(){act(async()=>{await lots.create({name:name.value,stratum:stratum.value,size:size.value,estimated_error_rate:rate.value,doc_prefix:prefix.value,description:description.value});name.value='';prefix.value=''})}</script><template><PageHeading index="01 / 批次底册" title="把抽样总体，逐批记在纸上。" note="文档编号由唯一批次前缀和00001起的序号组成。预估差错率只用于设计抽样，不是实测差错率。"/><div class="two-col"><section><Notice :message="lots.error.value"/><div class="table-wrap"><table><thead><tr><th>批次</th><th>风险层</th><th>份数</th><th>预估差错率</th><th>编号前缀</th></tr></thead><tbody><tr v-for="r in lots.items.value" :key="r.id"><td><strong>{{r.name}}</strong><small class="row-note">{{r.description}}</small></td><td>{{strataLabels[r.stratum]}}</td><td>{{r.size}}</td><td>{{pct(r.estimated_error_rate)}}</td><td>{{r.doc_prefix}}</td></tr></tbody></table></div></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新增档案批次</h2><label>批次名称<input v-model="name" required minlength="2"></label><label>风险层<select v-model="stratum"><option v-for="s in strata" :key="s" :value="s">{{strataLabels[s]}}</option></select></label><div class="form-pair"><label>文档份数<input type="number" v-model.number="size" min="1" max="5000"></label><label>预估差错率<input type="number" v-model.number="rate" min="0" max="1" step=".001"></label></div><label>文档前缀<input v-model="prefix" required minlength="2" pattern="[A-Za-z0-9-]+" placeholder="GL-202611-A"></label><label>估计来源<textarea v-model="description" rows="3"></textarea></label><Notice :message="error"/><button :disabled="busy">保存批次底册</button></form><aside v-else class="margin-note">只读账号可浏览批次。新增与修改需分析师权限。</aside></div></template>
